def transform(grid):
    n = len(grid)
    colors = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == color]
        if cells:
            area = (max(r for r,c in cells)-min(r for r,c in cells)+1) * (max(c for r,c in cells)-min(c for r,c in cells)+1)
            colors.append((area, color))
    colors.sort(reverse=True)
    out = [[0]*n for _ in range(n)]
    for level, (_, color) in enumerate(colors):
        size = n - 4*level
        start = 2*level
        for r in range(start, start+size):
            for c in range(start, start+size):
                out[r][c] = color
    return out
